CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT,slug TEXT UNIQUE NOT NULL,title TEXT NOT NULL,schedule TEXT NOT NULL,description TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>0));
CREATE TABLE IF NOT EXISTS registrations(id INTEGER PRIMARY KEY AUTOINCREMENT,event_id INTEGER NOT NULL REFERENCES events(id),name TEXT NOT NULL,email TEXT COLLATE NOCASE NOT NULL,organization TEXT NOT NULL,interests TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Confirmed' CHECK(status IN ('Confirmed','Checked in')),created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),UNIQUE(event_id,email));
